-- ====================================================================================================
-- MS SQL MASTER ATTENDANCE & BIOMETRIC SYNC SCRIPT (PRIMARY KEY SAFE & RECALCULATE READY)
-- Department: Purva Venezia (18 Corrected Employees across 26-Jul-2026 to 25-Aug-2026)
-- ====================================================================================================

USE [etimetracklite1];
GO

SET NOCOUNT ON;
PRINT '======================================================================';
PRINT '  Starting Master Attendance & Biometric Sync for Purva Venezia';
PRINT '======================================================================';
PRINT '';

-- 1. Create Temporary Tables for Bulk Operations
IF OBJECT_ID('tempdb..#CleanPunches') IS NOT NULL DROP TABLE #CleanPunches;
IF OBJECT_ID('tempdb..#CleanAttendance') IS NOT NULL DROP TABLE #CleanAttendance;

CREATE TABLE #CleanPunches (
    UserId VARCHAR(50),
    LogDate DATETIME,
    Direction VARCHAR(20),
    PRIMARY KEY (UserId, LogDate)
);

CREATE TABLE #CleanAttendance (
    EmployeeCode VARCHAR(50),
    AttendanceDate DATE,
    InTime DATETIME,
    OutTime DATETIME,
    Duration INT,
    Status VARCHAR(50)
);







PRINT '>>> Step 1: Cleaning rogue / conflicting punches in DeviceLogs and Partition Tables...';
-- 1.1 Clean main DeviceLogs
DELETE d
FROM dbo.DeviceLogs d
WHERE d.UserId IN (SELECT DISTINCT UserId FROM #CleanPunches)
  AND d.LogDate >= '2026-07-26 00:00:00' AND d.LogDate <= '2026-08-26 23:59:59'
  AND NOT EXISTS (
      SELECT 1 FROM #CleanPunches cp 
      WHERE cp.UserId = d.UserId AND cp.LogDate = d.LogDate
  );

-- 1.2 Clean July Partition Table (if exists)
IF OBJECT_ID('dbo.DeviceLogs_7_2026', 'U') IS NOT NULL
BEGIN
    DELETE d
    FROM dbo.DeviceLogs_7_2026 d
    WHERE d.UserId IN (SELECT DISTINCT UserId FROM #CleanPunches)
      AND d.LogDate >= '2026-07-26 00:00:00' AND d.LogDate <= '2026-07-31 23:59:59'
      AND NOT EXISTS (
          SELECT 1 FROM #CleanPunches cp 
          WHERE cp.UserId = d.UserId AND cp.LogDate = d.LogDate
      );
END

-- 1.3 Clean August Partition Table (if exists)
IF OBJECT_ID('dbo.DeviceLogs_8_2026', 'U') IS NOT NULL
BEGIN
    DELETE d
    FROM dbo.DeviceLogs_8_2026 d
    WHERE d.UserId IN (SELECT DISTINCT UserId FROM #CleanPunches)
      AND d.LogDate >= '2026-08-01 00:00:00' AND d.LogDate <= '2026-08-26 23:59:59'
      AND NOT EXISTS (
          SELECT 1 FROM #CleanPunches cp 
          WHERE cp.UserId = d.UserId AND cp.LogDate = d.LogDate
      );
END
PRINT '    ✅ Conflicting punches removed from all tables.';

PRINT '>>> Step 2: Inserting valid biometric punches into dbo.DeviceLogs...';
SELECT 
    cp.LogDate, 
    1, 
    cp.UserId, 
    cp.LogDate, 
    cp.Direction, 
    cp.Direction
FROM #CleanPunches cp
WHERE NOT EXISTS (
    SELECT 1 FROM dbo.DeviceLogs d WITH (NOLOCK)
    WHERE d.UserId = cp.UserId AND d.LogDate = cp.LogDate
);
PRINT '    ✅ All valid biometric punches synced into dbo.DeviceLogs.';

PRINT '>>> Step 3: Updating monthly partition tables (DeviceLogs_7_2026 & DeviceLogs_8_2026)...';
IF OBJECT_ID('dbo.DeviceLogs_7_2026', 'U') IS NOT NULL
BEGIN
    SELECT cp.LogDate, 1, cp.UserId, cp.LogDate, cp.Direction, cp.Direction
    FROM #CleanPunches cp
    WHERE MONTH(cp.LogDate) = 7 AND YEAR(cp.LogDate) = 2026
      AND NOT EXISTS (
          SELECT 1 FROM dbo.DeviceLogs_7_2026 d WITH (NOLOCK) 
          WHERE d.UserId = cp.UserId AND d.LogDate = cp.LogDate
      );
END

IF OBJECT_ID('dbo.DeviceLogs_8_2026', 'U') IS NOT NULL
BEGIN
    SELECT cp.LogDate, 1, cp.UserId, cp.LogDate, cp.Direction, cp.Direction
    FROM #CleanPunches cp
    WHERE MONTH(cp.LogDate) = 8 AND YEAR(cp.LogDate) = 2026
      AND NOT EXISTS (
          SELECT 1 FROM dbo.DeviceLogs_8_2026 d WITH (NOLOCK) 
          WHERE d.UserId = cp.UserId AND d.LogDate = cp.LogDate
      );
END
PRINT '    ✅ Monthly partition tables updated with zero duplicate errors.';

PRINT '>>> Step 4: Updating dbo.AttendanceLogs daily shift summaries...';
-- 4.1 Update existing records
UPDATE a
SET 
    a.InTime = ca.InTime,
    a.OutTime = ca.OutTime,
    a.Duration = ca.Duration,
    a.Status = ca.Status,
    a.Remarks = 'Excel Verified'
FROM dbo.AttendanceLogs a
JOIN dbo.Employees e ON a.EmployeeId = e.EmployeeId
JOIN #CleanAttendance ca ON LTRIM(RTRIM(CAST(e.EmployeeCode AS VARCHAR(50)))) = ca.EmployeeCode 
                        AND CAST(a.AttendanceDate AS DATE) = ca.AttendanceDate;

-- 4.2 Insert missing records
SELECT 
    e.EmployeeId, 
    CAST(ca.AttendanceDate AS DATETIME), 
    ca.InTime, 
    ca.OutTime, 
    ca.Duration, 
    ca.Status, 
    'Excel Verified'
FROM #CleanAttendance ca
JOIN dbo.Employees e ON LTRIM(RTRIM(CAST(e.EmployeeCode AS VARCHAR(50)))) = ca.EmployeeCode
WHERE NOT EXISTS (
    SELECT 1 FROM dbo.AttendanceLogs a 
    WHERE a.EmployeeId = e.EmployeeId AND CAST(a.AttendanceDate AS DATE) = ca.AttendanceDate
);
PRINT '    ✅ dbo.AttendanceLogs successfully updated.';

-- Clean up temp tables
DROP TABLE #CleanPunches;
DROP TABLE #CleanAttendance;

PRINT '';
PRINT '======================================================================';
PRINT '✅ MASTER ATTENDANCE & BIOMETRIC SYNC COMPLETED WITH ZERO ERRORS!';
PRINT '======================================================================';
GO

-- Verification: Check Abdul Khadar Days 18, 19, 20, 21
SELECT 
    e.EmployeeCode,
    e.EmployeeName,
    CONVERT(VARCHAR(10), a.AttendanceDate, 120) AS ShiftDate,
    CONVERT(VARCHAR(8), a.InTime, 108) AS InTime,
    CONVERT(VARCHAR(8), a.OutTime, 108) AS OutTime,
    a.Duration AS DurationMins,
    a.Status
FROM dbo.AttendanceLogs a WITH (NOLOCK)
JOIN dbo.Employees e WITH (NOLOCK) ON a.EmployeeId = e.EmployeeId
WHERE e.EmployeeCode = '420001'
  AND a.AttendanceDate >= '2026-08-18' AND a.AttendanceDate <= '2026-08-21'
ORDER BY a.AttendanceDate;
GO
